for(const [key,value] of Object.entries(extendedUiWords))if(!uiWords[key])uiWords[key]=value;
function translateText(value){if(lang==='ar')return String(value);const idx=lang==='fr'?0:1;const source=String(value);if(uiWords[source])return uiWords[source][idx];const prefixes=Object.keys(uiWords).filter(k=>k.length>=5).sort((a,b)=>b.length-a.length);for(const key of prefixes){if(source.startsWith(key)&&(key.endsWith(' ')||/[ :،—]/.test(source[key.length]||'')))return uiWords[key][idx]+source.slice(key.length)}return source}
function translateDom(root){if(lang==='ar'||!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){const raw=n.nodeValue,key=raw.trim();if(!key)continue;const translated=translateText(key);if(translated!==key)n.nodeValue=raw.replace(key,translated)}root.querySelectorAll('input,textarea,select,button').forEach(el=>{for(const a of ['placeholder','aria-label','title'])if(el.hasAttribute(a)){const translated=translateText(el.getAttribute(a));if(translated!==el.getAttribute(a))el.setAttribute(a,translated)}})}
const mimeFor=file=>file.type||({pdf:'application/pdf',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',txt:'text/plain',csv:'text/csv',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp'}[String(file.name).split('.').pop().toLowerCase()]||'application/octet-stream');
const tr=k=>dict[lang]?.[k]||k, today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, admin=()=>['platform_owner','institution_admin','admin'].includes(profile?.role), readOnlyYear=()=>!year?.is_current||!!year?.archived_at;
function toast(m){toastCounter++;let n=$('#toast');if(!n){n=document.createElement('div');n.id='toast';document.body.append(n)}n.textContent=translateText(m);n.classList.add('show');setTimeout(()=>n.classList.remove('show'),3200)}
function shell(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';const nav=['home','students','classes','attendance','sessions','tests','results','measurements','observations','notebook','team','reports','years','plans','settings'].filter(k=>k!=='team'||['platform_owner','institution_admin'].includes(profile.role));$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${logoUrl?`<img class="institution-logo" src="${esc(logoUrl)}" alt="شعار المؤسسة">`:'<div class="mark">SP</div>'}<div><b>SPORT</b><small>PERFORMANCE</small></div></div><div class="inst"><div class="avatar">${esc((inst?.name||'SP').slice(0,2))}</div><div><b>${esc(inst?.name||'المؤسسة الرياضية')}</b><small>${esc(profile?.full_name||user.email)}</small></div></div><nav>${nav.map(k=>`<button data-page="${k}" class="nav ${page===k?'active':''}"><i>${icons[k]||'◈'}</i><span>${tr(k)}</span></button>`).join('')}</nav><div class="sidefoot"><button id="language">${lang.toUpperCase()}　⇄</button><button id="logout">↪ ${tr('logout')}</button></div></aside><main class="main" ${watermarkUrl?`style="--inst-watermark:url('${esc(watermarkUrl)}')"`:''}><header class="top"><button class="mobile-menu" id="menu">☰</button><div><span class="eyebrow">SPORT PERFORMANCE / ${tr(page).toUpperCase()}</span><h1>${tr(page)}</h1></div><div class="topright"><select id="year-switcher" class="year-tag" aria-label="السنة الدراسية">${cache.years.map(y=>`<option value="${y.id}" ${year?.id===y.id?'selected':''}>${esc(y.name)}${y.is_current?' •':''}</option>`).join('')}</select><div class="user-chip"><span class="avatar small">${esc((profile?.full_name||'U').slice(0,1))}</span>${esc(profile?.full_name||'')}</div></div></header><section id="view" class="view"><div class="loading">${tr('loading')}…</div></section></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#logout').onclick=logout;$('#language').onclick=()=>{lang=({ar:'fr',fr:'en',en:'ar'})[lang];localStorage.setItem('sp_lang',lang);shell();render()};$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');const ys=$('#year-switcher');if(ys)ys.onchange=async()=>{try{await loadData(ys.value);shell();render()}catch(error){toast(error.message)}}}
const icons={home:'⌂',students:'♙',classes:'▦',attendance:'✓',sessions:'◷',tests:'◉',results:'▤',measurements:'⌁',observations:'◇',notebook:'▧',team:'♧',reports:'▥',years:'▣',settings:'⚙'};
let authListenerAttached=false;
async function init(){const c=cfg();if(!c.url||!c.key)return setup();try{if(!createClient){const sdk=await import('https://esm.sh/@supabase/supabase-js@2.57.0');createClient=sdk.createClient}sb=createClient(c.url,c.key);if(!authListenerAttached){sb.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){user=null;profile=null;login()}if(event==='PASSWORD_RECOVERY')passwordRecovery()});authListenerAttached=true}const{data,error}=await sb.auth.getSession();if(error)throw error;if(data.session&&/type=recovery/.test(location.hash))return passwordRecovery();if(!data.session)return login();user=data.session.user;await loadProfile()}catch(error){$('#app').innerHTML=`<div class="auth-wrap"><div class="auth-card"><div class="mark">SP</div><h1>تعذر الاتصال بالخدمة</h1><p class="muted">${esc(error.message||'تحقق من اتصال الإنترنت وإعدادات Supabase.')}</p><button class="primary" id="retry-connection">إعادة المحاولة</button></div></div>`;$('#retry-connection').onclick=init}}
function passwordRecovery(){ $('#app').innerHTML=`<div class="auth-wrap"><div class="auth-card"><div class="mark">SP</div><h1>تعيين كلمة مرور جديدة</h1><form id="recovery-form" class="form"><label>كلمة المرور الجديدة<input name="password" type="password" minlength="8" required></label><button class="primary">حفظ كلمة المرور</button></form></div></div>`;translateDom($('#app'));$('#recovery-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const{error}=await sb.auth.updateUser({password:f.get('password')});if(error)return toast(error.message);history.replaceState(null,'',location.pathname+location.search);toast('تم تحديث كلمة المرور');await init()}}
function setup(){ $('#app').innerHTML=`<div class="auth-wrap"><div class="auth-card"><div class="mark">SP</div><p class="eyebrow">INITIAL CONFIGURATION</p><h1>ربط التطبيق بقاعدة البيانات</h1><p class="muted">أدخل رابط مشروع Supabase ومفتاح Publishable/Anon. لا تضع service_role هنا.</p><form id="setup" class="form"><label>Supabase Project URL<input required type="url" name="url" placeholder="https://xxxx.supabase.co"></label><label>Publishable / anon key<textarea required name="key" rows="3"></textarea></label><button class="primary">حفظ ومتابعة</button></form></div></div>`;translateDom($('#app'));$('#setup').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);localStorage.setItem('sp_url',f.get('url').trim());localStorage.setItem('sp_key',f.get('key').trim());init()}}
function login(){ $('#app').innerHTML=`<div class="auth-wrap"><div class="auth-card"><div class="brand centered"><div class="mark">SP</div><div><b>SPORT</b><small>PERFORMANCE</small></div></div><p class="eyebrow">ATHLETIC PERFORMANCE MANAGEMENT</p><h1>مرحبًا بعودتك</h1><p class="muted">سجّل الدخول إلى فضاء مؤسستك.</p><form id="login" class="form"><label>البريد الإلكتروني<input name="email" type="email" required autocomplete="username"></label><label>كلمة المرور<input name="password" type="password" required autocomplete="current-password"></label><button class="primary">تسجيل الدخول</button></form><button class="link" id="forgot-password">نسيت كلمة المرور؟</button><button class="link" id="signup-open">إنشاء حساب جديد (بانتظار موافقة الإدارة)</button><button class="link" id="reconfig">تغيير إعدادات الاتصال</button></div></div>`;translateDom($('#app'));$('#login').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);let{error}=await sb.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(error)return toast(error.message);init()};$('#forgot-password').onclick=async()=>{const email=prompt(translateText('أدخل بريدك الإلكتروني لإرسال رابط إعادة التعيين'));if(!email)return;const{error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin});toast(error?error.message:'إذا كان البريد مسجلًا، سيصلك رابط إعادة التعيين')};$('#signup-open').onclick=signup;$('#reconfig').onclick=()=>{localStorage.removeItem('sp_url');localStorage.removeItem('sp_key');authListenerAttached=false;sb=null;setup()}}
function signup(){ $('#app').innerHTML=`<div class="auth-wrap"><div class="auth-card"><div class="mark">SP</div><h1>إنشاء حساب</h1><p class="muted">سيبقى الحساب معلّقًا حتى تعتمدك إدارة المؤسسة. لا تختَر صلاحياتك بنفسك.</p><form id="signup" class="form"><label>الاسم الكامل<input name="full_name" required></label><label>رمز / معرّف المؤسسة (slug) — اتركه فارغًا لحساب المالك الأول فقط<input name="institution_slug" placeholder="institution-code"></label><label>البريد الإلكتروني<input name="email" type="email" required></label><label>كلمة المرور (8 أحرف على الأقل)<input name="password" type="password" minlength="8" required></label><button class="primary">إنشاء الحساب</button></form><button class="link" id="back-login">العودة لتسجيل الدخول</button></div></div>`;translateDom($('#app'));$('#back-login').onclick=login;$('#signup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const{error}=await sb.auth.signUp({email:f.get('email'),password:f.get('password'),options:{data:{full_name:f.get('full_name'),institution_slug:f.get('institution_slug')}}});if(error)return toast(error.message);toast('تم إنشاء الحساب. انتظر موافقة الإدارة.');login()}}
async function loadProfile(){let{data,error}=await sb.from('profiles').select('*,institutions(*)').eq('id',user.id).maybeSingle();if(error)throw error;if(!data||data.status!=='active'){ $('#app').innerHTML=`<div class="auth-wrap"><div class="auth-card"><h2>الحساب غير مفعّل</h2><p>تم تسجيل الدخول لكن لم يُربط حسابك بمؤسسة أو لم تتم الموافقة عليه بعد.</p><button class="primary" id="retry-profile">إعادة المحاولة</button><button class="link" id="out">تسجيل الخروج</button></div></div>`;$('#out').onclick=logout;$('#retry-profile').onclick=()=>location.reload();translateDom($('#app'));return}profile=data;inst=data.institutions;await loadBranding();await loadData();shell();render()}
async function loadBranding(){logoUrl=null;watermarkUrl=null;if(!inst)return;for(const [column,target] of [['logo_url','logoUrl'],['watermark_url','watermarkUrl']]){const path=inst[column];if(!path)continue;const{data,error}=await sb.storage.from('sport-performance').createSignedUrl(path,604800);if(!error&&data?.signedUrl){if(target==='logoUrl')logoUrl=data.signedUrl;else watermarkUrl=data.signedUrl}}}
async function fetchAllRows(table,select='*',filters=[]){const rows=[];let from=0;while(true){let query=sb.from(table).select(select).order('created_at',{ascending:false}).order('id',{ascending:true}).range(from,from+999);for(const [column,value] of filters)query=query.eq(column,value);const{data,error}=await query;if(error)throw error;if(from>=50000&&data?.length)throw new Error(`تجاوزت بيانات ${table} حد التحميل الآمن 50000 صف`);rows.push(...(data||[]));if(!data||data.length<1000)break;from+=1000}return rows}
async function loadData(preferredYearId=undefined){const tables=['students','classes','sessions','attendance','test_definitions','test_results','institution_facilities','scale_versions','school_years','lesson_plans','observations','student_measurements','rehab_alerts'];for(const t of tables){const data=await fetchAllRows(t,'*',[['institution_id',profile.institution_id]]);cache[({test_definitions:'tests',test_results:'results',institution_facilities:'facilities',scale_versions:'scales',school_years:'years',lesson_plans:'plans',student_measurements:'measurements'}[t]||t)]=data}const memberFilters=profile.role==='platform_owner'?[]:[['institution_id',profile.institution_id]];cache.team=await fetchAllRows('profiles','id,full_name,email,role,status,institution_id',memberFilters);if(profile.role==='platform_owner')cache.institutions=await sb.from('institutions').select('id,name,slug').order('name').then(({data,error})=>{if(error)throw error;return data||[]});else cache.institutions=[];year=cache.years.find(y=>y.id===(preferredYearId===undefined?year?.id:preferredYearId))||cache.years.find(y=>y.is_current)||cache.years[0]||null;if(year){for(const k of ['students','classes','sessions','attendance','results','plans','observations','measurements','rehab_alerts'])cache[k]=(cache[k]||[]).filter(x=>x.school_year_id===year.id)}cache.notes=await fetchAllRows('coach_notebook','*',[['owner_id',user.id],['institution_id',profile.institution_id]]);if(year)cache.notes=cache.notes.filter(n=>n.school_year_id===year.id);studentsByNumber=new Map(cache.students.filter(s=>!s.archived).map(s=>[normalizeStudentNumber(s.student_number),s]));studentsById=new Map(cache.students.map(s=>[s.id,s]))}
async function writeBatches(table,rows,{upsert=false,onConflict}={}){for(let i=0;i<rows.length;i+=500){const batch=rows.slice(i,i+500);const result=upsert?await sb.from(table).upsert(batch,{onConflict}):await sb.from(table).insert(batch);if(result.error)throw result.error}}
function go(p){page=p;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('.top h1').textContent=tr(p);$('.eyebrow').textContent='SPORT PERFORMANCE / '+tr(p).toUpperCase();render()}
const btn=(label,action='')=>`<button class="primary" ${action?`id="${action}"`:''}>＋ ${label}</button>`;
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">لا توجد بيانات مسجلة</td></tr>`}</tbody></table></div>`}
const scoreLabel=r=>r.score!=null?String(r.score):(r.scale_version_id?'لا يوجد تطابق في BARÈME':'لا يوجد BARÈME');const attendanceLabel=v=>({present:'حاضر',absent:'غائب',late:'متأخر'}[v]||v||'—');const reasonLabel=v=>({ordinary:'غياب عادي',permission:'رخصة',exempt:'إعفاء',official_duty:'واجب'}[v]||v||'—');const roleLabel=v=>({platform_owner:'مالك المنصة',institution_admin:'مدير المؤسسة',admin:'إدارة',coach:'مدرب'}[v]||v||'—');const memberStatusLabel=v=>({pending:'بانتظار الموافقة',active:'مفعّل',rejected:'مرفوض',suspended:'موقوف'}[v]||v||'—');
function render(){let v=$('#view');if(!v)return;const data=cache;let html='';switch(page){case'home':html=`<div class="hero"><div><span class="eyebrow">WORKSPACE OVERVIEW</span><h2>الأداء يبدأ من التنظيم.</h2><p>مساحة عمل موحدة لمتابعة التلاميذ والحصص والنتائج.</p></div><div class="hero-mark">SP</div></div><div class="stats"><article><span>التلاميذ</span><b>${data.students.length}</b><small>مسجلون في المؤسسة</small></article><article><span>الحصص</span><b>${data.sessions.length}</b><small>إجمالي الحصص المسجلة</small></article><article><span>النتائج</span><b>${data.results.length}</b><small>نتائج الاختبارات</small></article><article><span>الاختبارات</span><b>${data.tests.filter(t=>t.is_active!==false).length}</b><small>اختبارات مفعلة</small></article></div><div class="panel"><h3>آخر الحصص</h3>${table(['التاريخ','المدرب','البداية','النهاية'],data.sessions.slice(0,8).map(s=>`<tr><td>${esc(s.session_date)}</td><td>${esc(s.coach_name_snapshot||'—')}</td><td>${esc(s.start_time||'—')}</td><td>${esc(s.end_time||'مفتوحة')}</td></tr>`).join(''))}</div>`;break;
case'students':html=`<div class="toolbar"><input id="q" placeholder="${tr('search')} الاسم أو الرقم"><select id="student-class-filter"><option value="">كل الأقسام</option>${data.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><div>${admin()&&!readOnlyYear()?btn('إضافة تلميذ','add-student'):''}${admin()&&!readOnlyYear()?'<button class="secondary" id="bulk-students">استيراد جماعي</button>':''}${!readOnlyYear()?'<button class=\"secondary\" id=\"export\">تصدير CSV</button>':''}<button class="secondary" id="export-students-xlsx">Excel XLSX</button></div></div><div class="panel"><div id="students-table">${studentsTable(filterStudents($('#q')?.value,$('#student-class-filter')?.value))}</div></div>`;break;
case'classes':html=`<div class="toolbar">${admin()&&!readOnlyYear()?btn('إضافة قسم','add-class'):''}</div><div class="cards">${data.classes.map(c=>`<article class="panel"><span class="eyebrow">CLASS</span><h2>${esc(c.name)}</h2><p>${data.students.filter(s=>s.class_id===c.id).length} تلميذ</p>${admin()&&!readOnlyYear()?`<button class="secondary" data-edit-class="${c.id}">تعديل القسم</button>`:''}</article>`).join('')||'<div class="panel empty">لا توجد أقسام</div>'}</div>`;break;
case'attendance':html=`<div class="panel"><h3>تسجيل الحضور السريع</h3><p class="muted">أدخل أرقام التلاميذ الحاضرين مفصولة بفواصل أو أسطر. سيتم عرض المطابقة قبل الحفظ.</p><label>الأرقام<textarea id="att-numbers" rows="5" placeholder="101, 102, 105"></textarea></label><div class="toolbar"><input type="date" id="att-date" value="${today()}"><select id="att-session"><option value="">اختر الحصة (ضروري لاحتساب التأهيل)</option>${data.sessions.filter(s=>!s.end_time&&s.coach_id===user.id).map(s=>`<option value="${s.id}">${esc(s.session_date)} — ${esc(s.start_time)}</option>`).join('')}</select><button class="primary" id="att-preview" ${readOnlyYear()?'disabled':''}>معاينة الأرقام</button></div><div id="att-preview-area"></div><hr><h3>تسجيل الغياب / التأخير</h3><label>أرقام التلاميذ<textarea id="abs-numbers" rows="3" placeholder="أرقام التلاميذ الغائبين"></textarea></label><div class="toolbar"><select id="abs-reason"><option value="ordinary">غياب عادي</option><option value="permission">رخصة</option><option value="exempt">إعفاء</option><option value="official_duty">واجب</option></select><select id="abs-status"><option value="absent">غائب</option><option value="late">متأخر</option></select><button class="primary" id="save-absence" ${readOnlyYear()?'disabled':''}>حفظ الحالات</button></div></div><div class="panel"><h3>تنبيهات العودة بعد الغياب</h3><p class="muted">تظهر بعد خمسة غيابات متتالية، وتبقى خلال حصة العودة والحصة الفعلية التالية التي يحضرها التلميذ.</p>${table(['التلميذ','تاريخ التنبيه','الحصص المتبقية','الإجراء'],data.rehab_alerts.filter(a=>a.returned_at&&a.remaining_sessions>0&&!a.handled_at).map(a=>`<tr><td>${esc(studentsById.get(a.student_id)?.full_name||'—')}</td><td>${esc(a.triggered_on)}</td><td>${a.remaining_sessions}</td><td><button class="secondary" data-rehab-handled="${a.id}">تمت المعالجة</button></td></tr>`).join(''))}</div><div class="panel"><h3>سجل تنبيهات التأهيل</h3>${table(['التلميذ','تاريخ التنبيه','الحصص المتبقية','الحالة'],data.rehab_alerts.map(a=>`<tr><td>${esc(studentsById.get(a.student_id)?.full_name||'—')}</td><td>${esc(a.triggered_on)}</td><td>${a.remaining_sessions}</td><td>${a.handled_at?'تمت المعالجة':a.remaining_sessions===0?'انتهى التنبيه':a.returned_at?'عاد إلى الحضور':'بانتظار العودة'}</td></tr>`).join(''))}</div><div class="panel"><h3>آخر التسجيلات</h3>${table(['التاريخ','التلميذ','الحالة','السبب'],data.attendance.slice(0,30).map(a=>`<tr><td>${esc(a.attendance_date)}</td><td>${esc(studentsById.get(a.student_id)?.full_name||'—')}</td><td>${esc(attendanceLabel(a.status))}</td><td>${esc(reasonLabel(a.absence_reason))}</td></tr>`).join(''))}</div>`;break;
case'sessions':html=`<div class="toolbar"><div><b>إدارة الحصص</b><p class="muted">تسجيل وقت البداية والنهاية مرتبط بالمدرب.</p></div><button class="primary" id="start-session" ${readOnlyYear()?'disabled':''}>بدء حصة جديدة</button></div><div class="panel">${table(['التاريخ','المدرب','وقت البداية','وقت النهاية','المدة'],data.sessions.map(s=>`<tr><td>${esc(s.session_date)}</td><td>${esc(s.coach_name_snapshot||'')}</td><td>${esc(s.start_time||'')}</td><td>${esc(s.end_time||'مفتوحة')}</td><td>${esc(s.duration_minutes!=null?s.duration_minutes+' د':'—')}</td><td>${!readOnlyYear()&&!s.end_time&&s.coach_id===user.id?`<button class="secondary" data-end-session="${s.id}">إنهاء الحصة</button>`:'—'}</td></tr>`).join(''))}</div>`;break;
case'tests':html=`<div class="toolbar"><h3>تعريف الاختبارات</h3>${admin()&&!readOnlyYear()?btn('إضافة اختبار','add-test'):''}</div><div class="panel">${table(['الاختبار','الوحدة','الحالة','الإجراء'],data.tests.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.unit||'—')}</td><td>${t.is_active===false?'غير مفعل':'مفعل'}</td><td>${admin()&&!readOnlyYear()?`<button class="secondary" data-edit-test="${t.id}">إعدادات</button><button class="secondary" data-toggle-test="${t.id}" data-active="${t.is_active===false?'false':'true'}">${t.is_active===false?'تفعيل':'تعطيل'}</button>`:'—'}</td></tr>`).join(''))}</div><div class="panel"><h3>إصدارات BARÈME</h3><p class="muted">يُدخل المسؤول القيم الرسمية الخاصة بالمؤسسة. لا توجد قيم افتراضية أو علامات مخترعة.</p>${admin()&&!readOnlyYear()?`<button class="secondary" id="scale-add">إضافة سلم تنقيط</button>`:''}${table(['الاختبار','الإصدار','ساري منذ','القيم الرسمية','تاريخ الإضافة'],data.scales.map(x=>`<tr><td>${esc(data.tests.find(t=>t.id===x.test_id)?.name||'—')}</td><td>${x.version}</td><td>${esc(x.valid_from)}</td><td>${esc((x.rules||[]).map(r=>`${r.rawValue} ← ${r.score}`).join('، '))}</td><td>${esc(x.created_at||'')}</td></tr>`).join(''))}</div>`;break;
case'results':html=`<div class="toolbar"><h3>النتائج الرياضية</h3>${admin()&&!readOnlyYear()?btn('إدخال نتيجة','add-result'):''}${admin()&&!readOnlyYear()?'<button class="secondary" id="bulk-results">استيراد نتائج جماعي</button>':''}${!readOnlyYear()?'<button class=\"secondary\" id=\"export-results\">تصدير CSV</button>':''}<button class="secondary" id="export-results-xlsx">Excel XLSX</button></div><div class="toolbar result-filters"><input id="result-q" placeholder="ابحث برقم التلميذ أو اسمه"><select id="result-test-filter"><option value="">كل الاختبارات</option>${data.tests.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><select id="result-class-filter"><option value="">كل الأقسام</option>${data.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="panel"><div id="results-table">${resultsTable([...data.results].sort((a,b)=>String(b.tested_on).localeCompare(String(a.tested_on))))}</div></div>`;break;case'measurements':html=`<div class="panel"><h3>القياسات البدنية</h3><p class="muted">الوزن والطول وBMI مع تاريخ القياس. تُعرض القياسات حسب السنة الدراسية.</p>${admin()&&!readOnlyYear()?btn('إضافة قياس','add-measure'):''}${table(['التاريخ','التلميذ','الوزن','الطول','BMI','اتجاه BMI'],[...data.measurements].sort((a,b)=>String(b.measured_on).localeCompare(String(a.measured_on))).map(m=>`<tr><td>${esc(m.measured_on)}</td><td>${esc(data.students.find(s=>s.id===m.student_id)?.full_name||'—')}</td><td>${esc(m.weight_kg??'—')}</td><td>${esc(m.height_m??'—')}</td><td>${esc(m.bmi??'—')}</td><td>${esc(bmiTrend(m.student_id))}</td></tr>`).join(''))}</div>`;break;
case'observations':html=`<div class="panel"><h3>ملاحظات التلاميذ</h3><p class="muted">ملاحظات المؤسسة المشتركة، وليست الكراس الشخصي للمدرب.</p>${!readOnlyYear()?btn('إضافة ملاحظة','add-observation'):''}${table(['التاريخ','التلميذ','الملاحظة'],data.observations.map(o=>`<tr><td>${esc(o.created_at)}</td><td>${esc(data.students.find(s=>s.id===o.student_id)?.full_name||'—')}</td><td>${esc(o.body)}</td></tr>`).join(''))}</div>`;break;
case'notebook':html=`<div class="panel"><h3>كراس المدرب الخاص</h3><p class="muted">المحتوى هنا خاص بحسابك ولا يظهر لبقية المدربين، ومحفوظ ضمن السنة الدراسية المحددة.</p>${readOnlyYear()?'<p class="muted">السنة مؤرشفة — الكراس للقراءة فقط.</p>':'<textarea id="private-note" rows="5" placeholder="اكتب ملاحظتك الخاصة…"></textarea><button class="primary" id="save-note">حفظ في كراسي</button>'}<div class="note-list">${data.notes.map(n=>`<article class="panel"><p>${esc(n.body)}</p><small>${esc(n.created_at)}</small>${!readOnlyYear()?`<button class="secondary" data-edit-note="${n.id}">تعديل الملاحظة</button><button class="secondary" data-delete-note="${n.id}">حذف الملاحظة</button>`:''}</article>`).join('')||'<p class="muted">لا توجد ملاحظات محفوظة.</p>'}</div></div>`;break;
case'team':html=`<div class="panel"><h3>الفريق والموافقات</h3><p class="muted">تُنفّذ الموافقات عبر دوال محمية في قاعدة البيانات.</p>${profile.role==='platform_owner'?btn('إضافة مؤسسة','create-institution'):''}${profile.role==='platform_owner'?table(['المؤسسة','رمز التسجيل'],data.institutions.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.slug)}</td></tr>`).join('')):''}${table(['الاسم','البريد','الدور','الحالة','الإجراء'],data.team.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${esc(x.email||'')}</td><td>${esc(roleLabel(x.role))}</td><td>${esc(memberStatusLabel(x.status))}</td><td>${['pending','rejected'].includes(x.status)?(profile.role==='platform_owner'?`<button class="secondary" data-approve-owner="${x.id}" data-institution="${esc(x.institution_id||'')}">اعتماد مدير مؤسسة</button>`:profile.role==='institution_admin'?`<button class="secondary" data-approve-member="${x.id}">اعتماد عضو</button><button class="secondary" data-reject-member="${x.id}">رفض</button>`:'—'):'—'}</td></tr>`).join(''))}</div>`;break;
case'reports':html=`<div class="stats"><article><span>عدد التلاميذ</span><b>${data.students.length}</b></article><article><span>الحضور المسجل</span><b>${data.attendance.length}</b></article><article><span>النتائج</span><b>${data.results.length}</b></article></div><div class="panel"><h3>ملخص الأقسام</h3>${table(['القسم','التلاميذ','حاضر','غائب','متأخر','نسبة الحضور من الحالات المسجلة','النتائج'],data.classes.map(c=>{const ids=new Set(data.students.filter(s=>s.class_id===c.id).map(s=>s.id)),a=data.attendance.filter(x=>ids.has(x.student_id)),present=a.filter(x=>x.status==='present').length,absent=a.filter(x=>x.status==='absent').length,late=a.filter(x=>x.status==='late').length,total=present+absent+late,rate=total?`${((present+late)/total*100).toFixed(1)}%`:'—';return `<tr><td>${esc(c.name)}</td><td>${ids.size}</td><td>${present}</td><td>${absent}</td><td>${late}</td><td>${rate}</td><td>${data.results.filter(r=>ids.has(r.student_id)).length}</td></tr>`}).join(''))}</div><div class="panel"><h3>ملخص نتائج الاختبارات</h3>${table(['الاختبار','عدد النتائج','متوسط العلامات المتاحة','بدون تطابق BARÈME'],data.tests.map(t=>{const rows=data.results.filter(r=>r.test_id===t.id),scores=rows.filter(r=>r.score!==null).map(r=>Number(r.score)),avg=scores.length?(scores.reduce((a,b)=>a+b,0)/scores.length).toFixed(2):'—';return `<tr><td>${esc(t.name)}</td><td>${rows.length}</td><td>${avg}</td><td>${rows.filter(r=>r.score===null).length}</td></tr>`}).join(''))}</div><div class="panel"><h3>تصدير البيانات</h3>${!readOnlyYear()?'<button class=\"secondary\" id=\"export\">تصدير قائمة التلاميذ CSV</button><button class=\"secondary\" id=\"export-results\">تصدير النتائج CSV</button><button class=\"secondary\" id=\"export-attendance\">تصدير الحضور CSV</button><button class=\"secondary\" id=\"export-measurements\">تصدير القياسات CSV</button><button class=\"secondary\" id=\"export-observations\">تصدير الملاحظات CSV</button><button class=\"secondary\" id=\"export-sessions\">تصدير الحصص CSV</button>':''}<button class="secondary" id="export-all-xlsx">تصدير السنة كاملة Excel XLSX</button>${!readOnlyYear()?'<button class=\"secondary\" id=\"print-report\">طباعة التقرير</button>':''}</div>`;break;
case'years':html=`<div class="panel"><h3>السنوات الدراسية</h3><p class="muted">السنة المؤرشفة للقراءة والتصدير فقط.</p>${admin()?btn('إنشاء سنة دراسية','add-year'):''}${table(['السنة','البداية','الحالة'],data.years.map(y=>`<tr><td>${esc(y.name)}</td><td>${esc(y.start_date||'')}</td><td>${y.is_current?'جارية':'مؤرشفة'}</td></tr>`).join(''))}</div>`;break;
case'plans':html=`<div class="toolbar"><div><h3>خطط ودروس الحصص</h3><p class="muted">تُعدّها الإدارة ويختارها المدرب عند بدء الحصة.</p></div>${admin()&&!readOnlyYear()?btn('إضافة درس','add-plan'):''}</div><div class="cards">${data.plans.map(p=>`<article class="panel"><span class="eyebrow">LESSON PLAN</span><h3>${esc(p.title)}</h3><p>${esc(p.content||'')}</p>${p.file_path?`<button class="secondary" data-plan-file="${esc(p.file_path)}">فتح الملف</button>`:''}</article>`).join('')||'<div class="panel empty">لا توجد دروس مسجلة لهذه السنة.</div>'}</div>`;break;case'settings':html=`<div class="panel"><h3>إعدادات المؤسسة</h3><p>المؤسسة: <b>${esc(inst?.name||'—')}</b></p><p>رمز المؤسسة (للتسجيل): <b>${esc(inst?.slug||'—')}</b></p><div class="panel"><h3>البنية التحتية والتجهيزات</h3>${admin()?'<button class="secondary" id="add-facility">إضافة منشأة / تجهيز</button>':''}${table(['الاسم','النوع','الوصف','الحالة','الإجراء'],data.facilities.map(f=>`<tr><td>${esc(f.name)}</td><td>${esc(f.facility_type)}</td><td>${esc(f.description)}</td><td>${f.is_available?'متاح':'غير متاح'}</td><td>${admin()?`<button class="secondary" data-facility-edit="${f.id}">تعديل</button><button class="secondary" data-facility-toggle="${f.id}" data-available="${f.is_available}">${f.is_available?'تعطيل':'تفعيل'}</button>`:'—'}</td></tr>`).join(''))}</div><p>البريد: ${esc(user.email)}</p><p class="muted">لتغيير عنوان Supabase أو المفتاح، استخدم شاشة إعداد الاتصال بعد تسجيل الخروج.</p>${admin()?`<div class="form"><label>شعار المؤسسة<input id="institution-logo" type="file" accept="image/png,image/jpeg,image/webp"></label><label>شعار العلامة المائية<input id="institution-watermark" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="secondary" id="save-branding">حفظ الهوية البصرية</button></div>`:''}<button class="secondary" id="refresh">تحديث البيانات</button></div>`;break;}
v.innerHTML=html;translateDom(v);bindPage()}
function bindClassActions(){document.querySelectorAll('[data-edit-class]').forEach(b=>b.onclick=()=>{const c=cache.classes.find(x=>x.id===b.dataset.editClass);if(!c)return;modal('تعديل القسم',`<label>اسم القسم<input name=\"name\" value=\"${esc(c.name)}\" required></label>`,async f=>{let{error}=await sb.from('classes').update({name:f.get('name').trim()}).eq('id',c.id);if(error)throw error;await loadData();render()})})}
function bmiTrend(studentId){const rows=cache.measurements.filter(m=>m.student_id===studentId&&m.bmi!=null).sort((a,b)=>String(a.measured_on).localeCompare(String(b.measured_on)));if(rows.length<2)return '—';const delta=Number((Number(rows.at(-1).bmi)-Number(rows.at(-2).bmi)).toFixed(2));return delta>0?`↑ +${delta}`:delta<0?`↓ ${delta}`:'→ 0'}
function resultsTable(rows){return table(['التاريخ','التلميذ','الاختبار','الأداء الخام','المدة (ث)','سرعة km/h','m/s','ثانية/20م','المسافة m','تكرار/دقيقة','تكرار/ثانية','ثانية/تكرار','العلامة','التصحيح'],rows.map(r=>{const student=studentsById.get(r.student_id);return `<tr><td>${esc(r.tested_on)}</td><td>${esc(student?.student_number||'—')} — ${esc(student?.full_name||'—')}</td><td>${esc(cache.tests.find(t=>t.id===r.test_id)?.name||'—')} (${esc(cache.tests.find(t=>t.id===r.test_id)?.unit||'')})</td><td>${esc(r.raw_value)}</td><td>${esc(r.duration_seconds??'—')}</td><td>${esc(r.speed_kmh??'—')}</td><td>${esc(r.speed_ms??'—')}</td><td>${esc(r.shuttle_seconds??'—')}</td><td>${esc(r.distance_m??'—')}</td><td>${esc(r.rate_per_minute??'—')}</td><td>${esc(r.rate_per_second??'—')}</td><td>${esc(r.average_rep_seconds??'—')}</td><td>${esc(scoreLabel(r))}</td><td>${admin()&&!readOnlyYear()?`<button class=\"secondary\" data-edit-result=\"${r.id}\">تصحيح</button>`:'—'}</td></tr>`}).join(''))}
function filterResults(){const q=($('#result-q')?.value||'').trim().toLowerCase(),testId=$('#result-test-filter')?.value||'',classId=$('#result-class-filter')?.value||'';return cache.results.filter(r=>{const student=studentsById.get(r.student_id);return (!q||normalizeStudentNumber(student?.student_number||'').toLowerCase().includes(normalizeStudentNumber(q).toLowerCase())||(student?.full_name||'').toLowerCase().includes(q))&&(!testId||r.test_id===testId)&&(!classId||student?.class_id===classId)})}
