function modal(title,fields,save){let m=document.createElement('div');m.className='modal-back';m.innerHTML=`<form class="modal form"><div class="modal-head"><h2>${title}</h2><button type="button" class="icon-btn" id="close">×</button></div>${fields}<div class="modal-actions"><button type="button" class="secondary" id="cancel">إلغاء</button><button class="primary">حفظ</button></div></form>`;document.body.append(m);translateDom(m);const bulkArea=m.querySelector('textarea[name=rows],textarea[name=rules]');const preview=m.querySelector('#bulk-preview');const testSelect=m.querySelector('select[name=test_id]'),durationInput=m.querySelector('input[name=duration_seconds]');if(testSelect&&durationInput){const speedInput=m.querySelector('input[name=speed_kmh]'),shuttleInput=m.querySelector('input[name=shuttles_completed]');const setDuration=()=>{const t=cache.tests.find(x=>x.id===testSelect.value);if(!durationInput.dataset.userEdited)durationInput.value=t?.duration_seconds||'';if(speedInput){speedInput.closest('label').hidden=!/navette/i.test(t?.name||'');if(speedInput.closest('label').hidden)speedInput.value=''}if(shuttleInput){shuttleInput.closest('label').hidden=!/navette/i.test(t?.name||'');if(shuttleInput.closest('label').hidden)shuttleInput.value=''}};testSelect.addEventListener('change',setDuration);durationInput.addEventListener('input',()=>durationInput.dataset.userEdited='1');setDuration()}if(bulkArea&&preview){const updatePreview=()=>{try{let parsed;if(bulkArea.name==='rules'){parsed=parseScalePaste(bulkArea.value);preview.innerHTML=`<b>معاينة:</b> ${parsed.length} قيمة صالحة<br>${parsed.slice(0,5).map(x=>`${x.rawValue} ← ${x.score}`).join(' · ')}`}else if(title.includes('التلاميذ')){parsed=parseStudentPaste(bulkArea.value);const dup=parsed.length-new Set(parsed.map(x=>x.student_number)).size,existing=parsed.filter(x=>cache.students.some(s=>String(s.student_number)===x.student_number)).length;preview.innerHTML=`<b>معاينة:</b> ${parsed.length} تلميذ — مكرر داخل الملف: ${dup} — موجود مسبقًا: ${existing}<br>${parsed.slice(0,5).map(x=>`${esc(x.student_number)} — ${esc(x.full_name)}`).join('<br>')}`}else{parsed=parsePastedTable(bulkArea.value,{minColumns:2}).filter((cells,i)=>!(i===0&&/^(student.?number|number|code|matricule|numéro|رقم|الرقم|الكود|رقم التلميذ|رقم الطالب)$/i.test(cells[0])&&/^(raw|raw.?value|performance|النتيجة|الأداء|résultat)$/i.test(cells[1]||'')));const missing=parsed.filter(x=>!studentsByNumber.has(normalizeStudentNumber(x[0]))).length,ids=parsed.map(x=>studentsByNumber.get(normalizeStudentNumber(x[0]))?.id).filter(Boolean),dupFile=ids.length-new Set(ids).size,bulkDate=m.querySelector('input[name=tested_on]')?.value||today(),dupExisting=parsed.filter(x=>{const st=studentsByNumber.get(normalizeStudentNumber(x[0]));return st&&cache.results.some(r=>r.student_id===st.id&&r.test_id===testSelect?.value&&r.tested_on===bulkDate)}).length;preview.innerHTML=`<b>معاينة:</b> ${parsed.length} نتيجة — أرقام غير معروفة/مؤرشفة: ${missing} — مكرر داخل الملف: ${dupFile} — موجود مسبقًا: ${dupExisting}<br>${parsed.slice(0,5).map(x=>x.map(esc).join(' — ')).join('<br>')}`} }catch(err){preview.textContent=err.message}translateDom(preview)};bulkArea.addEventListener('input',updatePreview);testSelect?.addEventListener('change',updatePreview);m.querySelector('input[name=tested_on]')?.addEventListener('change',updatePreview);updatePreview()}const close=()=>m.remove();$('#close',m).onclick=close;$('#cancel',m).onclick=close;m.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;const beforeToast=toastCounter;try{await save(new FormData(e.target));close();if(toastCounter===beforeToast)toast('تم الحفظ بنجاح')}catch(err){toast(err.message||'تعذر الحفظ');b.disabled=false}}}
function notifyRehabReturns(studentIds){const now=Date.now();const returned=(cache.rehab_alerts||[]).filter(a=>studentIds.includes(a.student_id)&&a.returned_at&&a.remaining_sessions>0&&!a.handled_at&&now-new Date(a.returned_at).getTime()<120000);if(returned.length)toast(`تنبيه تأهيل: عاد ${returned.length} تلميذ بعد غيابات متتالية`)}
async function saveAbsences(){if(readOnlyYear())return toast('السنة المؤرشفة للقراءة فقط');if(!$('#att-session')?.value)return toast('اختر الحصة المفتوحة أولاً');const nums=splitStudentNumbers($('#abs-numbers').value);if(!nums.length)return toast('أدخل أرقام التلاميذ');const found=nums.map(n=>studentsByNumber.get(n)).filter(Boolean);if(found.length!==nums.length)return toast(`أرقام غير معروفة؛ صحّحها قبل الحفظ: ${nums.filter(n=>!studentsByNumber.has(n)).slice(0,25).join('، ')}`);const status=$('#abs-status').value,reason=status==='absent'?$('#abs-reason').value:null;const rows=found.map(s=>({institution_id:profile.institution_id,school_year_id:year?.id,student_id:s.id,session_id:$('#att-session')?.value||null,attendance_date:$('#att-date').value||today(),status,absence_reason:reason,is_late:status==='late',recorded_by:user.id}));try{await writeBatches('attendance',rows,{upsert:true,onConflict:'student_id,attendance_date,session_id'})}catch(error){return toast(error.message)}await loadData();render();toast('تم حفظ الحالات');notifyRehabReturns(found.map(s=>s.id))}
function attendancePreview(){if(readOnlyYear())return toast('السنة المؤرشفة للقراءة فقط');if(!$('#att-session')?.value)return toast('اختر الحصة المفتوحة أولاً');let nums=splitStudentNumbers($('#att-numbers').value),found=nums.map(n=>studentsByNumber.get(n)).filter(Boolean),missing=nums.filter(n=>!studentsByNumber.has(n));let area=$('#att-preview-area');area.innerHTML=`<p>مطابقة: <b>${found.length}</b> — أرقام غير معروفة: <b>${missing.length}</b>${missing.length?` (${missing.map(esc).join('، ')})`:''}</p><p class="muted">${missing.length?'صحّح الأرقام غير المعروفة قبل الحفظ.':'سيتم تسجيل جميع الأرقام المطابقة كحاضرين.'}</p><button class="primary" id="confirm-att" ${found.length&&!missing.length?'':'disabled'}>تأكيد تسجيل ${found.length} حاضر</button>`;translateDom(area);$('#confirm-att').onclick=async()=>{let date=$('#att-date').value;let rows=found.map(s=>({institution_id:profile.institution_id,school_year_id:year?.id,student_id:s.id,session_id:$('#att-session')?.value||null,attendance_date:date,status:'present',recorded_by:user.id}));try{await writeBatches('attendance',rows,{upsert:true,onConflict:'student_id,attendance_date,session_id'})}catch(error){return toast(error.message)}await loadData();render();toast('تم تسجيل الحضور');notifyRehabReturns(found.map(s=>s.id))}}
async function endSession(id){if(readOnlyYear())return toast('السنة المؤرشفة للقراءة فقط');const s=cache.sessions.find(x=>x.id===id);if(!s||s.coach_id!==user.id||s.end_time)return toast('لا يمكن إنهاء هذه الحصة');const end=new Date().toTimeString().slice(0,8);const{error}=await sb.from('sessions').update({end_time:end}).eq('id',id).eq('coach_id',user.id).is('end_time',null);if(error)return toast(error.message);await loadData();render();toast('تم إنهاء الحصة وحفظ وقت النهاية')}
async function startSession(lessonPlanId=null){if(readOnlyYear())return toast('أنشئ سنة دراسية جارية أولاً');let{data,error}=await sb.from('sessions').insert({institution_id:profile.institution_id,school_year_id:year.id,coach_id:user.id,coach_name_snapshot:profile.full_name,lesson_plan_id:lessonPlanId,session_date:today(),start_time:new Date().toTimeString().slice(0,8)}).select().single();if(error)return toast(error.message);activeSession=data;await loadData();render();toast('بدأت الحصة')}
async function excel(rows,name){if(!rows?.length)return toast('لا توجد بيانات للتصدير');try{const XLSX=await import('https://esm.sh/xlsx@0.18.5');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Sport Performance');XLSX.writeFile(wb,name,{bookType:'xlsx'})}catch(error){toast('تعذر إنشاء ملف Excel: '+error.message)}}
function csv(rows,name){if(!rows.length)return toast('لا توجد بيانات');let txt=csvText(rows);let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
async function logout(){await sb?.auth.signOut();user=profile=inst=null;login()}
init();
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
